-- Venue Live Guest "Wedding Dayak Kenyah". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara dayak), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'dayak', 'Wedding Dayak Kenyah (adat)', 'dayak', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 139, 'center 38%',
  $t${"name":"Dayak Kenyah","orn":"diamond","ui":{"ivory":"#FBF3E3","white":"#FFFFFF","soft":"#EAD5B5","soft2":"#C58A3C","accent":"#9A2A1C","deep":"#2A1710","ink":"#2B1A12","mute":"#8A6A52","line":"#E6D2B2","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#F8EBD2","ink":"#2B1A12","accent":"#9A2A1C","gold":"#E3A81C","leaf":"#EAD5B5","hbg":"rgba(251,243,227,.94)","hline":"#E3A81C","motif":"diamond"},"hud":{"bg":"rgba(42,23,16,.9)","acc":"#F2C14E","on":"#2B1A12"},"scr":{"wine":"#2A1710","veil":"251,243,227"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'dayak');
